mapper.select:
SELECT bm_production_plan.*,MAX(bm_production_plan_item.end_time) as plan_end_date FROM bm_production_plan left join bm_production_plan_item on bm_production_plan_item.production_plan_id = bm_production_plan.id WHERE bm_production_plan.is_deleted = 0
and bm_production_plan.plan_name like concat('%',#{planName},'%')
and bm_production_plan.plan_type =#{planType}
and bm_production_plan.plan_state =#{planState}
GROUP BY bm_production_plan.id order by bm_production_plan.plan_state desc,bm_production_plan.create_time desc
